#include <iostream>
#include <cmath>

// Checks if a number is prime with O(sqrt(n)) complexity
bool isPrime(int n) {
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0) return false;
    for (int d = 3; d * d <= n; d += 2) {
        if (n % d == 0) return false;
    }
    return true;
}

// Reverses an integer
int reverseDigits(int n) {
    int reversed = 0;
    while (n > 0) {
        reversed = reversed * 10 + (n % 10);
        n /= 10;
    }
    return reversed;
}

// Demonstrates floor-based rounding to hundredths
double roundToHundredths(double val) {
    return std::floor(val * 100.0 + 0.5) / 100.0;
}

int main() {
    int num = 7631;
    std::cout << "Reversed of " << num << " is " << reverseDigits(num) << "\n";

    int testPrime = 29;
    std::cout << testPrime << (isPrime(testPrime) ? " is prime" : " is not prime") << "\n";

    double x = 45.678;
    std::cout << x << " rounded to hundredths: " << roundToHundredths(x) << "\n";
    return 0;
}

#include <iostream>

// Recursive GCD (Euclid's algorithm)
int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

// Towers of Hanoi solver
void solveHanoi(int n, int src, int dest, int aux) {
    if (n == 1) {
        std::cout << src << " -> " << dest << "\n";
        return;
    }
    solveHanoi(n - 1, src, aux, dest);
    std::cout << src << " -> " << dest << "\n";
    solveHanoi(n - 1, aux, dest, src);
}

int main() {
    std::cout << "GCD of 48 and 18: " << gcd(48, 18) << "\n";
    std::cout << "Hanoi moves for 3 disks (Peg 1 to 3):\n";
    solveHanoi(3, 1, 3, 2);
    return 0;
}
